update sc_plans set spec=jsonb_set(spec,'{shots}',coalesce(spec->'shots','[]'::jsonb) || $q$[{"n": 3, "id": "hw3_lead", "vid": "hwv3_lead", "img_prompt": "GHOST COSTUME: a plain white bedsheet worn over the whole body down to the ankles, two round eye holes, only the small orange pumpkin basket handle hanging out from under the sheet; the face, hair and hands are completely hidden. Halloween night at the bright entrance of the narrow alley under a warm streetlamp. Kachi flies low just ahead of a small child in a ghost costume, holding the corner of the white sheet in its beak and gently leading the little ghost down the alley toward the dark hanok gate at the far end. Pumpkin lanterns glow at the side gates. The magpie is exactly the character in the magpie reference image: a small round chibi magpie with a glossy black head, cream-white face and belly, big shiny dark-brown eyes, short black beak, dark navy-blue wings, a red knotted neckerchief and a small brown leather satchel. It does NOT hold a microphone. Style: handcrafted 3D miniature diorama photographed with a macro lens, tilt-shift, shallow depth of field, soft cinematic light, felt, clay, paper and wood textures with tiny hand-painted details, gentle film grain, warm nostalgic color grade, clay figurines with soft rounded faces and deeply emotional Pixar-like expressions, not photorealistic. Vertical 9:16 frame, main subject in the middle of the frame, a calm uncluttered area in the top fifth of the frame. Absolutely no text, no letters, no numbers, no hangul, no logos, no labels, no brand names, no watermark anywhere.", "refs": ["social/side/gen/c1_magpie.jpeg"], "reuse": null, "action": "Kachi flaps slowly and gives the corner of the white sheet one gentle tug; the little ghost takes one small step forward.", "dur": 5, "cap": "So Kachi went to find someone.", "detail": "하얀 천 유령(정체 숨김) — 까치가 이끈다"}, {"n": 4, "id": "hw4_home", "vid": "hwv4_home", "img_prompt": "GRANDMA: a small Korean grandma in her late seventies, silver hair in a low bun, round kind face with smile wrinkles, plum-purple quilted vest over a cream blouse, dark grey long skirt. BOY: a Korean boy about seven years old, round rosy cheeks, short black hair, a mustard-yellow knitted beanie, navy padded jacket, carrying a small round orange pumpkin-shaped basket with a cute smiling face. PLACE: a small old hanok house at the end of a narrow Seoul alley: grey-tiled roof with gently curved eaves, a weathered wooden double gate, a low grey stone wall, a single stone step in front of the gate. Halloween night in front of the hanok gate. The white ghost sheet has slipped back off the boy's head and hangs over his shoulders like a cape, showing his happy face and mustard-yellow beanie. The grandma kneels on the stone step and hugs him close, her eyes shut, happy tears, cheek against his beanie; her hands are hidden behind his back. Roasted chestnuts fill his orange pumpkin basket on the step. Behind them, through the open gate, the framed crayon drawing of the grandma and the boy in the yellow beanie under a red heart is clearly visible on the wall. Style: handcrafted 3D miniature diorama photographed with a macro lens, tilt-shift, shallow depth of field, soft cinematic light, felt, clay, paper and wood textures with tiny hand-painted details, gentle film grain, warm nostalgic color grade, clay figurines with soft rounded faces and deeply emotional Pixar-like expressions, not photorealistic. Vertical 9:16 frame, main subject in the middle of the frame, a calm uncluttered area in the top fifth of the frame. Absolutely no text, no letters, no numbers, no hangul, no logos, no labels, no brand names, no watermark anywhere.", "refs": ["social/side/gen/hw2_alone.jpeg"], "reuse": null, "action": "The grandma holds the boy a little closer and slowly rocks; the boy smiles with closed eyes; the warm gate light glows.", "dur": 5, "cap": "He came home for Halloween.", "detail": "노란 비니 = 액자 그림 속 그 꼬마(손주) — 반전"}]$q$::jsonb) where id='P261031-halloween-gotgam'